def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    last_me, last_opp = history[-1]

    opp_c = 0
    opp_d = 0
    for a, b in history:
        if b == 'C':
            opp_c += 1
        else:
            opp_d += 1

    recent = history[-10:]
    rec_opp_d = 0
    for a, b in recent:
        if b == 'D':
            rec_opp_d += 1

    opp_run = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            opp_run += 1
        else:
            break

    provoked = 0
    unprovoked = 0
    unpunished = 0
    for i in range(1, n):
        prev_me = history[i - 1][0]
        curr_opp = history[i][1]
        if prev_me == 'C':
            if curr_opp == 'D':
                unprovoked += 1
        else:
            if curr_opp == 'D':
                provoked += 1
            else:
                unpunished += 1

    if opp_c == 0:
        return 'D'
    if opp_d >= 3 and opp_d >= opp_c * 2:
        return 'D'
    if rec_opp_d >= 7:
        return 'D'
    if opp_run >= 4:
        return 'D'
    if opp_run >= 3 and last_me == 'C':
        return 'D'
    if unprovoked >= 4 and (opp_d >= unprovoked or rec_opp_d >= 3):
        return 'D'
    if unprovoked >= 7:
        return 'D'

    if opp_d == 0 and n >= 80:
        if unpunished >= 2:
            return 'D'
        if last_opp == 'C' and last_me == 'C':
            if unpunished >= 1 or n in (80, 82):
                return 'D'
        return 'C'

    if last_opp == 'D':
        if last_me == 'D':
            if opp_d >= opp_c or rec_opp_d >= 5:
                return 'D'
            return 'C'
        if n >= 2 and history[-2][0] == 'D' and rec_opp_d <= 3 and unprovoked <= 1:
            return 'C'
        if opp_d <= 2 and rec_opp_d <= 1 and unprovoked <= 1 and n >= 20:
            return 'C'
        return 'D'

    if last_me == 'D' and unpunished >= 2 and unprovoked == 0 and provoked == 0 and opp_d <= 1 and n >= 80:
        return 'D'
    if rec_opp_d >= 5 and unprovoked >= 3:
        return 'D'

    return 'C'
